int minSwaps(vector<int>& a) {
    int n = a.size(), k = accumulate(a.begin(), a.end(), 0); if (!k) return 0; int cur = 0; for (int i = 0; i < k; i++) cur += a[i]; int best = cur;
    for (int i = k; i < n + k; i++) { cur += a[i % n] - a[(i - k) % n]; best = max(best, cur); } return k - best;
}
